/**
 * Unit tests for DOMNodePointer.getLocalName
 */
public class DOMNodePointer_getLocalName_TriageGen0Test {

    @Test
    public void testGetLocalName_WithNonNullLocalName() {
        // Scenario 1: node.getLocalName() returns a non-null value.
        // This covers the first branch: if (localName != null) { return localName; }
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn("myLocalName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("myLocalName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndNoColonInNodeName() {
        // Scenario 2: node.getLocalName() is null and node.getNodeName() has no ':'
        // This covers the branch: index < 0 ? name : ...
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("simpleName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("simpleName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndColonInNodeName() {
        // Scenario 3: node.getLocalName() is null and node.getNodeName() contains ':'
        // This covers the branch: ... : name.substring(index + 1)
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("prefix:localName");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("localName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndColonAtEnd() {
        // Scenario 4: node.getLocalName() is null and node.getNodeName() ends with ':'
        // Edge case for substring logic
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn("prefix:");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndColonAtStart() {
        // Scenario 5: node.getLocalName() is null and node.getNodeName() starts with ':'
        Node mockNode = mock(Node.class);
        when(mockNode.getLocalName()).thenReturn(null);
        when(mockNode.getNodeName()).thenReturn(":onlySuffix");

        String result = DOMNodePointer.getLocalName(mockNode);

        assertEquals("onlySuffix", result);
    }
}
